create schema if not exists lab;
create table if not exists lab.roster (student_id text primary key, email text unique not null, section text not null, auth_id text unique, allowed_attempts integer not null default 1 check(allowed_attempts between 1 and 2));
create table if not exists lab.instructors (auth_id text primary key);
create table if not exists lab.assignments (id uuid primary key default gen_random_uuid(), title text not null, opens_at timestamptz, closes_at timestamptz, check(closes_at > opens_at));
create table if not exists lab.attempts (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references lab.assignments, student_id text not null references lab.roster, attempt_no int not null check(attempt_no between 1 and 2), case_no int not null check(case_no between 1 and 5), workload jsonb not null, draft jsonb not null default '{}'::jsonb, version int not null default 0, updated_at timestamptz not null default now(), submitted_at timestamptz, unique(assignment_id, student_id, attempt_no));
create table if not exists lab.predictions (attempt_id uuid not null references lab.attempts, experiment text not null, answers jsonb not null, locked_at timestamptz not null default now(), primary key(attempt_id,experiment));
create table if not exists lab.experiment_runs (id bigint generated always as identity primary key, attempt_id uuid not null references lab.attempts, experiment text not null, results jsonb not null, created_at timestamptz not null default now());
create table if not exists lab.reports (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references lab.attempts, version int not null, snapshot jsonb not null, created_at timestamptz not null default now(), final boolean not null default false);
create table if not exists lab.grades (attempt_id uuid primary key references lab.attempts, auto_score numeric check(auto_score between 0 and 60), manual_score numeric check(manual_score between 0 and 40), feedback text, updated_at timestamptz default now());
create table if not exists lab.attachments (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references lab.attempts, object_key text unique not null, mime_type text not null, bytes int not null check(bytes between 1 and 5242880), created_at timestamptz not null default now());
create index if not exists runs_attempt_idx on lab.experiment_runs(attempt_id,created_at);
create index if not exists reports_attempt_idx on lab.reports(attempt_id,created_at);
alter table lab.roster enable row level security;
alter table lab.instructors enable row level security;
alter table lab.assignments enable row level security;
alter table lab.attempts enable row level security;
alter table lab.predictions enable row level security;
alter table lab.experiment_runs enable row level security;
alter table lab.reports enable row level security;
alter table lab.grades enable row level security;
alter table lab.attachments enable row level security;
revoke all on schema lab from public;
revoke all on all tables in schema lab from public;
